const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Arizona boundary
  const arizona = ee.FeatureCollection('TIGER/2018/States')
    .filter(ee.Filter.eq('NAME', 'Arizona'))
    .geometry();

  // 2. Load MODIS Aqua LST collection
  const modisLST = ee.ImageCollection('MODIS/006/MYD11A1')
    .select('LST_Day_1km', 'QC_Day');

  // Quality masking function
  function maskQuality(image) {
    const qc = image.select('QC_Day');
    const mask = qc.bitwiseAnd(3).eq(0); // Good quality (bits 0-1 = 00)
    return image.select('LST_Day_1km').updateMask(mask).multiply(0.02); // Scale to Kelvin
  }

  // 3. Get 2017 data (July 15-21)
  const col2017 = modisLST
    .filterDate('2017-07-15', '2017-07-22')
    .filterBounds(arizona)
    .map(maskQuality);

  const size2017 = col2017.size().getInfo();
  console.log('2017 Images found:', size2017);

  if (size2017 === 0) {
    console.log('No data for 2017 period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Get 2001-2010 average (July 15-21 each year)
  const years = ee.List.sequence(2001, 2010);

  const historicalImages = years.map(function(year) {
    const startDate = ee.Date.fromYMD(year, 7, 15);
    const endDate = startDate.advance(7, 'day');

    const yearCol = modisLST
      .filterDate(startDate, endDate)
      .filterBounds(arizona)
      .map(maskQuality);

    return yearCol.mean().set('year', year);
  });

  const colHistorical = ee.ImageCollection.fromImages(historicalImages);
  const sizeHistorical = colHistorical.size().getInfo();
  console.log('Historical period images:', sizeHistorical);

  if (sizeHistorical === 0) {
    console.log('No data for historical period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Calculate means
  const img2017 = col2017.mean();
  const imgHistorical = colHistorical.mean();

  // Check pixel counts
  const count2017 = img2017.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: arizona,
    scale: 3000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const countHistorical = imgHistorical.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: arizona,
    scale: 3000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  console.log('2017 valid pixels:', count2017);
  console.log('Historical valid pixels:', countHistorical);

  if (count2017 === 0 || countHistorical === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 6. Calculate mean temperatures
  const temp2017 = img2017.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: arizona,
    scale: 3000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const tempHistorical = imgHistorical.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: arizona,
    scale: 3000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  console.log('2017 mean temp (K):', temp2017 ? temp2017.toFixed(2) : 'null');
  console.log('2001-2010 mean temp (K):', tempHistorical ? tempHistorical.toFixed(2) : 'null');

  // 7. Validation and answer
  if (temp2017 === null || tempHistorical === null || 
      temp2017 < 200 || temp2017 > 400 || 
      tempHistorical < 200 || tempHistorical > 400) {
    console.log('Invalid temperature values.');
    console.log('<answer>C3</answer>');
    return;
  }

  const tempDiff = temp2017 - tempHistorical;
  console.log('Temperature difference (K):', tempDiff.toFixed(2));

  if (temp2017 > tempHistorical) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
